import {section,table,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq,inlineMath as im} from './math.js';
import {traceLab,mountTrace,cells} from './array-patterns-tools.js';
import {lstmCell,unroll,exitProfiles,exitDistribution,scaling,mixResidual,passCompute,timingFrames} from './recurrence-model.js';
export const recurrenceMeta={slug:'models/recurrence',title:'Recurrent and Looped Models',description:'Follow a state through gates, repeated blocks, early exit, aligned updates, recirculated caches and full-bandwidth latent feedback; separate parameter reuse from compute savings.',date:'2026-05-07',updated:'2026-10-14',topicPath:['models'],tags:['LSTM','Ouro','looped transformer','LoopMoE','DeepLoop','Recirculation','Full-Bandwidth Transformer','Nanbeige 4.2','latent feedback','early exit'],learningGoals:['Distinguish recurrence across tokens from repeated computation within a token.','Account for reused parameters, effective depth, gradients and cache choices.','Connect recurrence mechanisms to their measured benefits and limitations.'],related:['models/transformers','models/attention','models/moe','execution/decoding','execution/speculation','training/parallelism'],prototype:true,visibility:'public',kind:'dense-topic'};
export const recurrenceAliases=['ai/architectures/sequence-models/long-short-term-memory-network','ai/architectures/transformers/deeploop-residual-scaling-for-looped-transformers','ai/architectures/transformers/looped-language-models-ouro','ai/architectures/transformers/moe-looped-language-models','ai/architectures/transformers/recirculation-inference-time-recurrence',"ai/architectures/transformers/full-bandwidth-transformer-latent-feedback"];
export const recurrenceSections=[['axes','What is repeated, and when?'],['lstm','Carry a memory through tokens'],['gates','See a cell retain and write'],['reuse','More executions, not more stored weights'],['unroll','Follow shared blocks through three rounds'],['halting','Choose when to stop'],['exit-lab','Hazards are not exit probabilities'],['loop-cache','Keep the right state for each loop'],['ouro-evidence','What Ouro establishes'],['sparse','Repeat a conditional subnetwork'],['sparse-evidence','Quality and savings are different measurements'],['alignment','Shared weights collect cross-use updates'],['scaling','Control aligned update growth'],['scaling-lab','Compare the depth-dependent factors'],['deeploop-evidence','Evidence for residual scaling'],['recirculation','Refine a cached interpretation'],['mix-lab','Mix directions, not arbitrary magnitudes'],['timing','Readout and refinement happen at different times'],['recirc-adapter','Learn how much state to recirculate'],['recirc-evidence','Where recirculation helps—and where it does not'],['feedback','Carry a wide state into the next token'],['feedback-modes','Use feedback at the prompt boundary'],['feedback-training','Train a sequential channel in parallel passes'],['feedback-stability','Make repeated feedback survive its own inputs'],['feedback-evidence','Separate feedback gains from extra training'],['nanbeige','A fixed-loop model recipe'],['implementation','Checks before claiming a saving'],['sources','Sources and connected topics']];
const vec=x=>'['+x.map(v=>v.toFixed(3)).join(', ')+']';
const loops=unroll(2,3);
function loopBody(f){return `<h4>${f.complete?'Six visits complete':`Round ${f.round}: execute block ${f.block}`}</h4>${cells(['W₁','W₂'],f.complete?[]:[f.block-1])}<p>Stored block parameter sets: ${f.stored}. Executed visits: ${f.step}/${f.effective}. Visit history: ${f.visited.map(v=>`W${v.physical}`).join(' → ')||'none yet'}.</p><p>The weights stay the same between rounds. The incoming hidden state does not. A shared block need not produce the same result on its second visit.</p>`;}
function cellBody(f){const c=lstmCell(3,f,.5,1,.8);return `${table('Synthetic scalar cell; c(previous)=3, input gate=0.5, candidate=1, output gate=0.8',['Operation','Value'],[['Retain f·c(previous)',c.retained.toFixed(3)],['Write i·candidate',c.written.toFixed(3)],['New cell c',c.cell.toFixed(3)],['Visible state 0.8·tanh(c)',c.hidden.toFixed(3)]])}<p>Direct carry-path derivative with gates held fixed: ${f.toFixed(2)}. This is not the complete recurrent Jacobian: gate values also depend on the previous state.</p>`;}
function exitBody(profile,q){const f=exitDistribution(exitProfiles[profile],q);return `${table('Four-loop budget; last loop takes all remaining mass',['Loop','Conditional hazard','Mass arriving','Exit mass','Cumulative mass'],f.rows.map(r=>[`${r.loop}${r.loop===f.selected?' ← chosen':''}`,r.loop===4?'forced':r.hazard.toFixed(3),r.survival.toFixed(3),r.mass.toFixed(3),r.cdf.toFixed(3)]))}<p>Threshold q=${q.toFixed(2)} selects loop ${f.selected}. Mean exit depth under the distribution: ${f.expected.toFixed(3)}; entropy ${f.entropy.toFixed(3)} nats; KL to uniform ${f.kl.toFixed(3)} nats. Quantile selection is deterministic, not a draw from this distribution.</p>`;}
function scaleBody(r,p,aligned){const s=scaling(4,r,p,aligned);return `${table('Four physical blocks; local scaling factor only, not measured gradient norm',['Quantity','Value'],[['Effective blocks N',s.n],['Residual sublayers M=2N',s.m],['Alignment factor κ',s.kappa],['Skip α',s.alpha.toFixed(5)],['Initialization β',s.beta.toFixed(5)],[im(String.raw`M\kappa\left(\frac\beta\alpha\right)^2`),s.bound.toFixed(6)]])}<p>p=${p}, ${aligned?'aligned κ=R':'decorrelated κ=1'}, R=${r}. At ${im(String.raw`p=\frac14`)}, the displayed factor is ${im(String.raw`\frac{\kappa}{2}`)}. At ${im(String.raw`p=\frac12`)} with ${im(String.raw`\kappa=R`)}, it is ${im(String.raw`\frac1{8K}=\frac1{32}`)}. Hidden constants, optimizer effects and evolution after initialization are not simulated.</p>`;}
function mixBody(alpha,add){const beta=add?1:1-alpha,f=mixResidual([1,0],[-4,3],alpha,beta),px=x=>150+100*x,py=y=>170-100*y;return `<svg viewBox="0 0 300 260" role="img" aria-label="Destination vector [1,0], rescaled source [-0.8,0.6], mixed vector ${vec(f.mixed)}"><path d="M25 170H275 M150 40V225" stroke="#93748a"/><path d="M150 170L250 170" stroke="#bad6fa" stroke-width="3"/><path d="M150 170L70 110" stroke="#bd738e" stroke-width="3"/><path d="M150 170L${px(f.mixed[0])} ${py(f.mixed[1])}" stroke="#eadbad" stroke-width="4"/><circle cx="${px(f.mixed[0])}" cy="${py(f.mixed[1])}" r="5" fill="#eadbad"/><text x="155" y="55">y</text><text x="275" y="190">x</text><text x="30" y="245">Equal scale on both axes</text></svg><p>Blue: destination [1,0]. Burgundy: source rescaled from [−4,3] to [−0.8,0.6]. Cream: ${im(String.raw`\beta h_d+\alpha s'`)} = ${vec(f.mixed)}. α=${alpha.toFixed(2)}, β=${beta.toFixed(2)}; result norm ${f.mixedNorm.toFixed(3)}.</p><p>${add?'Residual addition keeps the destination and adds a source contribution.':'Convex mixing interpolates two equal-norm directions; the result need not have unit norm.'} This is a two-dimensional illustration, not a fitted model activation.</p>`;}
function timingBody(f){const labels={loop:['A: shared stack','A: same stack again','Readout → B'],feedback:['A: top state h₀','Fuse h₀ with embedding B','B: stack → h₁'],recirculation:['A: ordinary readout','A: earlier-state remix','Later token: refined KV']};return `<h4>${f.kind}: ${f.label}</h4>${cells(labels[f.kind],[f.active])}<p>${f.detail}</p><p>Logical dependencies only. The trace does not implement cache replacement or predict hardware overlap.</p>`;}
export function recurrenceReader(link){return topic(recurrenceMeta,recurrenceSections,'More processing can reuse weights, refine memory or carry a state. These are different decisions.',`
<p>A model can spend more computation without storing a larger collection of weights. It can also retain a state that ordinary token-by-token execution does not expose to the next input. Both ideas involve recurrence, but they change different dependencies.</p><p>Start with the state being carried. Then ask when it is reused, when a token is emitted and which cached values later attention reads. These questions explain both the potential benefit and the implementation cost.</p>
${section('axes','What is repeated, and when?',`${table('Do not collapse all recurrence into “run the model again”',['Mechanism','State transition','When next-token logits are read'],[['LSTM','Previous token’s cell and hidden state → next token','After the current recurrent update'],['Looped Transformer','Current token’s hidden state → another visit to shared blocks','After the chosen number of visits'],['Recirculation','Current token’s deeper residual → an earlier residual; update history','Ordinary pass predicts; refinement helps later tokens'],['Full-bandwidth feedback','Previous token’s top state → next token’s input','After one stack execution per generated token']])}<p>These are not stages of one inevitable replacement sequence. LSTM is a classical sequence recurrence. Ouro (2025) studies latent depth recurrence. Sparse Layers (May 2026) combines that reuse with sparse experts. DeepLoop (July 2026) studies its update scaling. Recirculation and Full-Bandwidth Transformer (August 2026) explore different state paths.</p><p>Visible chain-of-thought adds emitted tokens. Latent recurrence adds internal transitions. Neither guarantees better reasoning: more computation can repeat a mistake. See <a href="${link('execution/decoding')}">Decoding and Sampling →</a> for generation policies, and <a href="${link('execution/speculation')}">Speculative Decoding →</a> for accelerating a target distribution rather than changing its model.</p>`)}
${section('lstm','Carry a memory through tokens',`<p>An ordinary RNN repeatedly transforms its hidden state. An LSTM adds a cell state c, with explicit retention and writing. The hidden state h exposes a gated, bounded transformation of that memory.</p>${eq(String.raw`\begin{aligned}z_t&=[h_{t-1},x_t]\\f_t&=\sigma(W_fz_t+b_f),&i_t&=\sigma(W_iz_t+b_i)\\g_t&=\tanh(W_gz_t+b_g),&o_t&=\sigma(W_oz_t+b_o)\\c_t&=f_t\odot c_{t-1}+i_t\odot g_t,&h_t&=o_t\odot\tanh(c_t)\end{aligned}`,'Forget f, input i, candidate g and output o have cell width. ⊙ means coordinate-wise multiplication.')}<p>The forget gate selects old cell content to retain. The input gate controls the new candidate write. The output gate controls which transformed cell coordinates become visible. Sigmoid maps the three gates into [0,1]; tanh bounds the candidate and visible transformation, not the cell itself.</p><p>Initialize h and c, then apply the same parameter sets at each sequence position. Gates can be computed together from z; the output gate does not have to be calculated after the new cell. A forget value near one preserves the direct cell path. A value near zero removes it.</p><p>The additive carry path helps preserve gradients, but does not guarantee stable training. Gate derivatives and all other paths remain part of the full Jacobian. Repeated forget values below one still multiply into a shrinking direct path.</p><p>At fixed input/hidden widths, processing T tokens is O(T). Dense gate work is more precisely ${im(String.raw`O(Td(d+d_{\mathrm{input}}))`)}. Keeping only the latest inference state needs O(d) state; returning every output or storing backpropagation activations grows with T. LSTMs have been used for forecasting, speech, translation and sequence classification; that list is not a current performance recommendation.</p><details><summary>Implement the cell and carry both states</summary><p>Use floating tensors on one device and with one dtype. Input x has shape [B,I]; h and c have shape [B,H]. Stack the four gate matrices into W[4H,H+I], with rows ordered forget, input, candidate, output. The combined bias b has shape [4H]. Concatenation uses [h,x].</p><pre tabindex="0" role="region" aria-label="LSTM cell reference"><code>import torch

def lstm_step(x, h, c, W, b):
    f, i, g, o = (torch.cat((h, x), -1) @ W.T + b).chunk(4, -1)
    c_next = f.sigmoid() * c + i.sigmoid() * g.tanh()
    h_next = o.sigmoid() * c_next.tanh()
    return h_next, c_next
</code></pre><p>Separate per-gate matrices are equivalent to this stacked layout. PyTorch LSTMCell instead stores input, forget, candidate, output rows, two input/state matrices and two biases. Reorder its rows, concatenate its state matrix before its input matrix, and add its biases before comparing outputs. ${cite('https://docs.pytorch.org/docs/2.14/generated/torch.nn.LSTMCell.html','PyTorch LSTMCell layout')} </p><p>The sequence wrapper accepts x[T,B,I]. Reset states for independent sequences; provide both states to continue the same sequence. It keeps cell histories as well as hidden outputs for inspection. The empty sequence returns empty histories and the unchanged initial states.</p><pre tabindex="0" role="region" aria-label="LSTM sequence reference"><code>def lstm_sequence(x, W, b, state=None):
    T, B, _ = x.shape
    H = W.shape[0] // 4
    h, c = (x.new_zeros(B, H), x.new_zeros(B, H)) if state is None else state
    hidden, memory = [], []
    for token in x:
        h, c = lstm_step(token, h, c, W, b)
        hidden.append(h)
        memory.append(c)
    hs = torch.stack(hidden) if T else x.new_empty(0, B, H)
    cs = torch.stack(memory) if T else x.new_empty(0, B, H)
    return hs, cs, (h, c)
</code></pre><p>For [1,2,3], reshape the input to [3,1,1], supply W and b, then call the wrapper. Values depend on those weights; the sequence alone does not determine the final state. This reference has no padding mask, projection, peephole connections, dropout or mixed-precision policy. A padded batch needs length-aware state updates. Full backpropagation retains the graph; detaching a carried state deliberately changes the gradient horizon.</p></details>`)}
${section('gates','See a cell retain and write',`<div class="topic-scene" data-cell-lab><h3>Change retention without changing the write</h3><label>Forget gate<input type="range" min="0" max="1" step="0.05" value="0.8" aria-label="Forget gate"></label><div data-body>${cellBody(.8)}</div></div><p>The cell can hold a magnitude larger than one, while tanh bounds the visible state before its output gate. These numbers are assigned for explanation, not learned from a sequence such as [1,2,3].</p>`)}
${section('reuse','More executions, not more stored weights',`<p>A looped stack stores K blocks and executes them R times. Its effective block depth is N=KR. An untied stack of N blocks stores distinct weights at each visit. A tied stack sends changed states through the same weights.</p>${eq(String.raw`h^{(r+1)}=F_\phi(h^{(r)}),\qquad N_{\rm stored}=K,\qquad N_{\rm executed}=KR`,'This schematic omits loop embeddings, normalization, cache policy and halting.')}<p>Parameter memory can shrink relative to an equally deep untied stack. Arithmetic does not shrink merely because a matrix was visited before. Sequential depth can increase latency. The KV cache may need separate states for each loop even though the parameters are shared.</p><p>Visible chain-of-thought consumes extra sequence positions, context and generation-cache work. Latent looping can refine a state without emitting those extra tokens. It still executes repeated blocks and may store separate loop caches. A vocabulary bottleneck is avoided at those internal transitions, not proof that their computation is useful reasoning.</p><p>For an MoE, distinguish total stored expert weights, active experts per visit and repeated active operations. A 6ND training proxy must count the effective active parameter operations over all repeated visits; deduplicating reused matrices understates compute. Attention’s sequence-length work and serving overhead also fall outside that simple proxy.</p>`)}
${section('unroll','Follow shared blocks through three rounds',traceLab('loop-unroll','Two physical blocks, six executed visits','Step through each visit. The weight identities remain W₁ and W₂.',loops,0,loopBody,'Seven manual states include the initial state and completion. No autoplay; no trained outputs or timing claim.'))}
${section('halting','Choose when to stop',`<p>Fixed looping allocates the same maximum depth everywhere. An adaptive gate can decide that a token has received enough processing. Ouro applies a dense projection and sigmoid to the final-layer state at each loop. Its conditional halt probability is a hazard, not the unconditional chance that this loop is the exit.</p>${eq(String.raw`\begin{aligned}\Pr(T=t)&=\lambda_t\prod_{j<t}(1-\lambda_j),\quad 1\le t<R\\\Pr(T=R)&=\prod_{j<R}(1-\lambda_j)\end{aligned}`,'R≥1 is an integer budget; hazards satisfy 0≤λ≤1. The last loop forces an exit. λₜ applies only to mass that survived earlier loops.')}<p>During training, Ouro executes all allowed loops and computes a loss at every possible exit. It combines these losses with the learned exit masses. Early termination is an inference decision, not a shortcut in this training objective. A penalty toward a uniform exit prior discourages all training mass from collapsing onto one loop. Such collapse can reinforce itself: a loop gets more loss weight, learns more, becomes more confident and receives still more weight.</p>${eq(String.raw`\mathcal L=\sum_{t=1}^R\Pr(T=t)\mathcal L_t+\beta D_{\rm KL}(P\|\operatorname{Uniform}_R),\qquad D_{\rm KL}(P\|\operatorname{Uniform}_R)=\log R-H(P)`,`Uses natural logs and normalized exit mass, with ${im(String.raw`0\log 0=0`)}. For fixed R and ${im(String.raw`\beta\ge0`)} this is an entropy reward plus a constant. Entropy does not guarantee correct predictions.`)}<p>The reported inference gate uses the first loop whose cumulative exit mass reaches a threshold q. This is deterministic quantile selection, not sampling T. A uniform prior does not mean all tokens actually stop at every loop equally often.</p><p>Why not favor shallow exits from the start? An early-biased geometric prior reduces the loss weight reaching later loops. Those loops can remain undertrained, making early exits look artificially preferable. Ouro’s four-loop, 776M-parameter prior ablation reports lower loss with a uniform prior. This is evidence for that setup, not a universal rule for adaptive computation.</p><p>Stage I trains the model and gates jointly. Stage II freezes the language model and trains only the gate. Detached per-loop losses supply a signal about marginal improvement versus extra compute. The second stage changes depth allocation, not the frozen model’s per-depth predictions. ${cite('https://arxiv.org/html/2510.25741v4','Ouro: halting and training')}</p>`)}
${section('exit-lab','Hazards are not exit probabilities',`<div class="topic-scene" data-exit-lab><h3>Where does the surviving mass go?</h3><label>Hazard profile<select aria-label="Exit hazard profile"><option value="uniform">Uniform exit mass</option><option value="early">Early-biased</option><option value="late">Late-biased</option></select></label><label>Quantile threshold<input type="range" min="0" max="1" step="0.05" value="0.5" aria-label="Exit quantile"></label><div data-body>${exitBody('uniform',.5)}</div></div><p>Uniform exit mass requires hazards ${im(String.raw`\frac14`)}, ${im(String.raw`\frac13`)}, ${im(String.raw`\frac12`)} and a forced final exit—not four hazards of 1/4. A low-entropy gate may be confidently wrong. Mean exit depth is a distribution statistic, not this quantile policy’s measured average serving depth.</p>`)}
${section('loop-cache','Keep the right state for each loop',`<p>During parallel prompt processing, each loop can produce a different key/value history. A token’s later loop should attend to a compatible loop history. Replacing this with every previous token’s individually selected exit state introduces a different dependency and can prevent the same parallel prefill schedule.</p><p>Ouro’s decode experiments compare full per-loop caches with reusing the first, last or averaged loop cache. In this four-loop ablation, “last” means the fourth-loop cache, not each token’s adaptively selected exit cache. These are approximations, not mathematically identical histories. In the checked table, full cache gives GSM8K 78.92 and MATH500 82.40. First-cache reuse gives 18.73 and 8.43; last gives 78.85 and 80.40; average gives 78.73 and 78.52.</p><p>Last/average reuse cuts the four-loop decode cache by about 4× in that setup, but MATH500 drops by 2.00/3.88 points. Do not summarize this as equal quality everywhere. The paper separately reports that sharing prefill cache hurts GSM8K by over ten points. Prompt and decode cache policies must be evaluated separately. ${cite('https://arxiv.org/html/2510.25741v4','Ouro cache ablations')}</p>`)}
${section('ouro-evidence','What Ouro establishes',`<p>The original report discusses 1.4B and 2.6B models and thinking variants, with about 7.7T total training tokens. The 2.6B branch is initialized by duplicating non-embedding layers from the smaller checkpoint after an initial 3T-token stage. The later phases also improve data quality and relax the duplicated model. This is a training recipe, not a clean parameter-only comparison.</p><p>The checked revision describes early eight-loop loss oscillations, then a reduction to four loops. The 1.4B model has 24 stored layers; the 2.6B branch has 48. The reported base 2.6B model exceeds Qwen3-Base 8B on selected reasoning benchmarks; Thinking variants are separately compared with 7B–8B reasoning models. Neither comparison establishes equal overall quality or matched compute.</p><p>Table 8 lists Qwen3 8B at 36T training tokens, Gemma3 12B at 12T, and Ouro 2.6B at 7.7T. These are different parameter and data budgets. Parameter efficiency must not be read as training-compute efficiency.</p><p>In synthetic biography experiments, more loops do not add new factual storage capacity in the same way as more independent weights. Tasks that manipulate already represented facts can benefit from two or four loops. Running beyond trained depth can help easier cases, but harder cases can peak around three or four loops and then degrade. “Keep looping until correct” is not a supported policy.</p><p>Universal Transformers and PonderNet provide related recurrence/halting ideas. <a href="${link('execution/decoding#guidance')}">LoopCD</a> extrapolates differences between recurrent-state output logits and belongs with decoding. Parameter reuse, halting and cache reuse each need their own ablation; none is a universal smaller-model substitute.</p>`)}
${section('sparse','Repeat a conditional subnetwork',`<p>A dense shared block is reused with a changed input. An MoE adds another source of variation: the router can select different experts on later visits. It does not make the dense alternative’s outputs identical.</p><p>Sparse Layers compares dense Base, dense Loop, untied MoE and LoopMoE. The main loop setting stores eight layers and executes two rounds, against sixteen untied layers. It uses MHA, RoPE, SwiGLU and Pre-RMSNorm. The MoE uses top-k token-choice routing: each token selects two of eight experts, with load-balance and router-z penalties.</p>${table('Two independent architecture choices; main comparison has sixteen effective layers',['Architecture','FFN','Stored layer sets','Loop passes'],[['Base','Dense','16','1'],['Loop','Dense','8','2'],['MoE','Sparse','16','1'],['LoopMoE','Sparse','8','2']])}<p>The authors propose that distinct expert paths relieve the expressivity constraint of tied dense FFNs. This hypothesis differs from the measured loss ranking. A dense shared FFN also receives changed states; it is not an identical-output machine.</p><p>Across most layers, 4–14% of tokens choose identical experts across the two rounds and 25–53% choose disjoint sets; most overlap partially. Layer seven is an exception: 37% exact overlap and 3% disjoint routing. The authors speculate that this layer stabilizes representations near the loop boundary. These observations show changing conditional paths, not proof that routing causes the benchmark gains. See <a href="${link('models/moe')}">MoE →</a> for the router and balancing mechanisms.</p>${table('Illustrative top-2 routes; not measured token examples',['First visit','Second visit','Overlap'],[['[1, 3]','[1, 3]','Identical: two shared experts'],['[1, 3]','[3, 5]','Partial: one shared expert'],['[1, 3]','[5, 7]','Disjoint: no shared experts']])}<p>Changed routing can expose four distinct experts across two visits while selecting only two per visit. Expert count alone does not establish better reasoning.</p><p>The experiments use a 10B-token FineWeb-Edu sample, GPT-2 tokenization, AdamW, WSD scheduling and μP width transfer from 128 to 1,024. Width transfer changes validation loss by under 1% relatively in the tested setting; transferring to a changed depth is less straightforward. ${cite('https://arxiv.org/html/2605.09165v1','Sparse Layers setup')}</p>`)}
${section('sparse-evidence','Quality and savings are different measurements',`<p>At iso-FLOP budgets 5×10¹⁶, 2×10¹⁷, 5×10¹⁷ and 10¹⁸, validation-loss ordering favors MoE, then LoopMoE, Base and Loop. Base and LoopMoE fitted scaling slopes are about 0.076 and 0.077: a favorable offset is not a fundamentally different scaling exponent.</p>${table('Core9 evaluation at the 10¹⁸ budget; original reported model sizes',['Model','Stored parameters','Core9 score'],[['Loop','168M','37.4'],['Base','246M','38.7'],['LoopMoE','216M','39.6'],['MoE','366M','36.4']])}<p>MoE has the best validation loss here but the lowest Core9 score. Training objective and downstream evaluation are not interchangeable. These are small models: tested active counts reach roughly 305M and stored MoE counts roughly 711M, not frontier deployments.</p><p>Training-free early exit inspects an intermediate normalized state through the LM head. Low token entropy is confidence, not correctness. The policy exits at the first candidate boundary whose entropy falls below a threshold τ. The threshold is swept to form a compute–quality curve; no extra exit head is trained.</p><p>Why inspect loop boundaries? Every loop ends in the same physical layers used before the final vocabulary projection. The authors hypothesize that these output-facing layers make earlier boundaries more suitable for readout. Untied intermediate layers do not share that final-layer role.</p><p>The logit lens applies the final normalization and LM head to intermediate states. It then compares each resulting distribution with the full-depth distribution:</p>${eq(String.raw`\operatorname{JSD}(p_\ell,p_L)=\tfrac12 D_{\rm KL}(p_\ell\|m)+\tfrac12 D_{\rm KL}(p_L\|m),\qquad m=\tfrac12(p_\ell+p_L)`,'pℓ is the intermediate vocabulary distribution; pL is the final distribution. With natural logs, JSD lies in [0, log 2]; divide by log 2 to normalize to [0,1].')}<p>On the tested 10¹⁸-FLOP models, agreement improves sharply at loop boundaries. The analysis counts normalized JSD below 0.5 as convergence. Agreement with the final output is not agreement with the true answer. This diagnostic supports the output-facing-layer explanation; it does not guarantee every early exit is correct.</p>${table('Same sixteen effective layers and width 704 in the loop-count comparison',['Physical layers × loops','Early boundaries','Final boundary'],[['8×2','1','After visit 16'],['4×4','3','After visit 16'],['2×8','7','After visit 16']])}<p>A model with R loops has R−1 early loop boundaries. Untied sixteen-layer models can exit at fifteen intermediate layers. More candidate points alone therefore do not explain the looped advantage.</p>${table('Perplexity when targeting 10% theoretical FLOP savings',['Model','Full execution','Early exit'],[['Base','34.8','55.4'],['MoE','34.8','75.7'],['Loop','36.2','50.2'],['LoopMoE 8×2','35.9','51.0'],['LoopMoE 4×4','35.4','44.3'],['LoopMoE 2×8','37.3','42.0']])}<p>More loop boundaries improve this exit tradeoff, but the full-depth quality changes too. Theoretical FLOP savings are not measured request throughput or latency. Fixed effective depth and mostly width scaling limit extrapolation to much deeper networks.</p>`)}
${section('alignment','Shared weights collect cross-use updates',`<p>Reusing parameters changes how an optimizer update affects the whole unrolled computation. In an untied stack, each use receives its own gradient. With tied parameters, all use-gradients are summed into one update, and that update is read again at every use.</p>${eq(String.raw`\begin{aligned}\Delta F_{\rm untied}&\approx\sum_rU_rG_r\\\Delta\phi_{\rm tied}&\approx\sum_tG_t,\qquad\Delta F_{\rm tied}\approx\left(\sum_rU_r\right)\left(\sum_tG_t\right)\end{aligned}`,'Schematic first-order update: a common signed optimizer step is suppressed. U denotes an output Jacobian acting on the matching parameter-update vector G. The tied expression contains cross-use terms.')}<p>The issue is not gradient correlation alone. Both write directions and output sensitivities can align. DeepLoop represents their combined effect with an alignment factor κ. Under its local assumptions, κ lies between zero and the reuse count R. Decorrelated uses can give O(1); coherent alignment can give Θ(R).</p><p>These are modeled regimes, not a direct measurement of every model’s κ. Reusing one parameter object is also different from initializing several independent copies to equal values: the latter still makes separate optimizer updates.</p><p>With ${im(String.raw`R=3`)}, the tied expression has nine write/read pairings: three diagonal terms and six cross-visit terms. The untied expression has only the three paired terms. Alignment decides whether the cross terms reinforce or cancel.</p>`)}
${section('scaling','Control aligned update growth',`<p>DeepLoop studies a residual form with a scaled skip and selected initialization gains. For ${im(String.raw`N=KR`)} effective blocks and ${im(String.raw`M=2N`)} residual sublayers, use ${im(String.raw`\alpha=(2N)^p`)} and ${im(String.raw`\beta=(8N)^{-p}`)}.</p>${eq(String.raw`\begin{aligned}x_{i+1}&=\operatorname{Norm}\!\left[\alpha x_i+f_i(x_i;\phi_i)\right]\\\text{local update factor}&\propto M\kappa\left(\frac\beta\alpha\right)^2\end{aligned}`,'β initializes selected matrices once. It is not a second multiplier to apply at every forward visit.')}<p>The baseline and DeepLoop use the same looped backbone, tied embeddings and input-embedding RMSNorm. Data, optimizer and seed are held fixed. The baseline uses ${im(String.raw`\alpha=\beta=1`)}; DeepLoop enables the scaling rule. The residual expression above has no additional inner normalization. ${cite('https://arxiv.org/html/2607.13491v1','DeepLoop equations and comparison')}</p>${eq(String.raw`\begin{aligned}p=\tfrac14:&\quad\frac\beta\alpha=\frac1{2\sqrt N},\quad M\kappa\left(\frac\beta\alpha\right)^2=\frac\kappa2\\p=\tfrac12:&\quad\frac\beta\alpha=\frac1{4N},\quad M\kappa\left(\frac\beta\alpha\right)^2=\frac\kappa{8N}=\frac1{8K}\quad(\kappa=R)\end{aligned}`,'N=KR and M=2N. The final equality assumes aligned κ=R and positive K,R.')}<p>At the DeepNorm exponent, aligned reuse leaves a factor proportional to R. The DeepLoop exponent removes that growth in this local bound.</p><p>More generally, keep K fixed and assume ${im(String.raw`\kappa=\Theta(R^\gamma),\quad\gamma\in[0,1]`)}. Bounded growth in this local model requires ${im(String.raw`p\ge\frac{1+\gamma}{4}`)}. </p><p>This is not a convergence theorem. The argument assumes visit-wise update and output-sensitivity scales of ${im(String.raw`O(\beta/\alpha)`)} near initialization. Hidden constants can depend on the optimizer, width and architecture. Higher p weakens the effective branch scale and can slow useful learning. The small-reuse sweep does not identify a globally optimal exponent. </p><p>At R=3 on GPT-2 small, seven exponents from 0.30 to 0.60 were tested with up to five seeds each. The short runs compare step-2,000 validation where available; failed runs use a trailing training-loss surrogate. Values below 0.45 failed in the tested seeds; 0.45 was mixed; values at least 0.50 were reliable in this setup. Comparing only converged seeds hides the failed trials.</p><details><summary>Initialize once, then reuse the same blocks</summary><p>For full backpropagation, N counts K physical blocks visited R times. The constructor below returns the two gains. K and R must be positive integers. p is finite and nonnegative; p=0 is the unscaled baseline, not the conservative DeepLoop choice.</p><pre tabindex="0" role="region" aria-label="Loop scaling reference"><code>import math

def loop_scales(K, R, p=0.5):
    if type(K) is not int or type(R) is not int or min(K, R) &lt; 1:
        raise ValueError("positive integer block and round counts required")
    if not math.isfinite(p) or p &lt; 0:
        raise ValueError("finite nonnegative exponent required")
    N = K * R
    return (2 * N) ** p, (8 * N) ** (-p)
</code></pre><p>Supply only the prescribed residual-branch matrices: attention value/output projections and feed-forward matrices. Do not scale every model parameter indiscriminately. Choose the base initializer for the architecture, then apply β once during model construction.</p><pre tabindex="0" role="region" aria-label="Shared matrix initialization reference"><code>import torch

def initialize_shared_once(matrices, base_initializer, beta):
    seen = set()
    with torch.no_grad():
        for weight in matrices:
            if id(weight) in seen:
                continue
            seen.add(id(weight))
            base_initializer(weight)
            weight.mul_(beta)
</code></pre><p>This function deduplicates the supplied parameter objects within one call. It does not prevent accidental reinitialization on a later call. Avoid distinct parameter objects sharing storage. Build the selected inventory and initialize it once; do not initialize inside a loop or after loading a checkpoint.</p><pre tabindex="0" role="region" aria-label="Shared stack execution reference"><code>def residual_sublayer(x, branch, norm, alpha):
    return norm(alpha * x + branch(x))

def run_shared_stack(x, blocks, rounds):
    if type(rounds) is not int or rounds &lt; 1:
        raise ValueError("positive integer round count required")
    blocks = tuple(blocks)
    if not blocks:
        raise ValueError("at least one physical block required")
    for _ in range(rounds):
        for block in blocks:
            x = block(x)
    return x
</code></pre><p>Each block must implement its attention and feed-forward sublayers with the chosen normalization, shapes and causal cache policy. The helper shows parameter reuse, not a complete Transformer. Norm acts after the scaled skip and branch sum. β is absent from this forward expression because initialization already applied it. Register each shared parameter once in optimizer groups. Log activation, branch, gradient and update scales by physical block and visit.</p><p>For detached or truncated recurrence, use gradient-visible sublayer visits in the local update analysis. The full-forward K×R helper alone cannot determine the correct gain for a hierarchical schedule.</p></details>`)}
${section('scaling-lab','Compare the depth-dependent factors',`<div class="topic-scene" data-scaling-lab><h3>Keep four stored blocks; change reuse</h3><label>Loop count<input type="range" min="1" max="16" step="1" value="4" aria-label="Scaling loop count"></label><label>Exponent<select aria-label="Residual scaling exponent"><option value="0.25">p=1/4</option><option value="0.375">p=3/8</option><option value="0.5" selected>p=1/2</option></select></label><label>Regime<select aria-label="Use alignment"><option value="aligned">Aligned κ=R</option><option value="decorrelated">Decorrelated κ=1</option></select></label><div data-body>${scaleBody(4,.5,true)}</div></div><p>The formulas show why a reuse-sensitive scale was proposed. They cannot tell you whether a trained checkpoint will have a specific gradient magnitude, loss or stability boundary.</p>`)}
${section('deeploop-evidence','Evidence for residual scaling',`${table('FineWeb-Edu 50B-token loss; same comparison setup, one seed',['Model','R','Baseline','DeepLoop'],[['GPT-2 small','1','2.8627','2.8631'],['small','3','2.8077','2.7917'],['small','5','2.7910','2.7679'],['small','7','2.7700','2.7514'],['GPT-2 medium','1','2.6253','2.6264'],['medium','3','2.5779','2.5627'],['medium','5','2.5640','2.5444'],['medium','7','2.5558','2.5280']])}<p>The runs use context 1,024 and 100K updates. Small uses four H200 GPUs; medium uses eight. Non-looped results are nearly tied. The small-model advantage peaks at R=5; the medium-model advantage grows through R=7. At R=7, the medium checkpoint improves seven of eight tasks in both zero- and one-shot evaluation. PIQA is the exception. The harness uses acc, not acc_norm, and an unweighted eight-task mean. This is not a guarantee on each task, seed or model scale.</p><p>For the hierarchical reasoning model, distinguish forward unrolling from gradient-visible depth. Earlier cycles are truncated; the analyzed last segment has M_g=24 residual sublayers and N_g=12 blocks. Per-module reuse is what matters, not a single arbitrary whole-program loop count.</p>${table('Reported ARC-AGI-1 voted accuracy; hierarchical-model experiment',['Voting budget','Baseline','DeepLoop'],[['1','31.50','35.50'],['2','36.50','39.75'],['10','41.50','44.25'],['100','47.50','49.75'],['1,000','50.75','51.50']])}<p>The original note records a four-seed check around the budget-two setting with approximately 0.5-point standard deviation. These conditions remain distinct from the single-seed language-model table. Local initialization analysis, small models and particular optimizer settings do not establish frontier/MoE convergence or a universal training recipe.</p>`)}
${section('recirculation','Refine a cached interpretation',`<p>A token’s shallow state is cached before its deeper interpretation is complete. Later attention can revisit the cached state, but ordinary caching does not retroactively replace it with the deeper interpretation. Think of “bank” in a fishing context: an earlier layer may retain an ambiguous representation even after later layers select the river meaning. A later ATM question can reactivate the financial association. The motivating critical-token activation-patching study reduced contextualization errors by 60%. That targeted intervention differs from applying recirculation to every token.</p><p>Recirculation sends a deeper residual at source layer s into an earlier destination d&lt;s, then reruns downstream computation. The basic method freezes the language model. It is not merely repeating a whole shared stack before every readout.</p>${eq(String.raw` s'=h_s\frac{\|h_d\|_2}{\max(\|h_s\|_2,\varepsilon)},\qquad\widetilde h_d=\alpha s'+\beta h_d`,'Match the source magnitude to the destination; then combine their directions. ε>0 makes the clamp well-defined. A zero source remains zero.')}<p>Norm matching makes α more interpretable. It does not prove that coordinates at the two depths represent the same concepts. Layer choice matters. Reported calibrated pairs are 11→4 for Gemma3 1B, 18→9 for 4B and 35→16 for 12B; layer-zero destinations work poorly in the tested sweep.</p><p>Calibration uses 1.5M tokens from arXiv, C4 and PG-19. Thus “training-free” still includes a calibration search. The fixed setting uses ${im(String.raw`\alpha\approx0.15`)}; the 1B model benefits from convex ${im(String.raw`\beta=1-\alpha`)}, while larger tested models benefit from ${im(String.raw`\beta=1`)} residual addition. For 1B, ramp α over the first ten positions using the rule below. These are model-specific choices.</p>${eq(String.raw`\alpha_t=\alpha\min\!\left(\frac{t}{10},1\right)`,'t≥0 is the position used by the ramp. Fix the zero/one-based indexing convention before applying it in an implementation.')}<p>The fixed mixer adds no projection between depths. Residual additions make shared feature directions plausible, but normalization and depth-specific roles can change their interpretation. The layer sweep is evidence of compatibility, not a proof that all layers share a semantic coordinate system. ${cite('https://arxiv.org/html/2608.17981v1','Recirculation mechanism')}</p>`)}
${section('mix-lab','Mix directions, not arbitrary magnitudes',`<div class="topic-scene" data-mix-lab><h3>A later direction enters an earlier state</h3><label>Source coefficient α<input type="range" min="0" max="0.5" step="0.05" value="0.15" aria-label="Recirculation source coefficient"></label><label>Destination coefficient<select aria-label="Recirculation mixing rule"><option value="convex">β=1−α: convex</option><option value="addition">β=1: addition</option></select></label><div data-body>${mixBody(.15,false)}</div></div><details><summary>Fixed residual mixer: a complete tensor operation</summary><p>Inputs have equal shape [..., d], dtype and device. Scalar coefficients or tensors broadcastable to that shape are accepted. Norms and source rescaling use float32; the scaled vector then returns to the source dtype. Converting a large ratio to float16 before multiplying can overflow, including 0×infinity for a zero source. This ordering corrects that edge case in the original sketch. This reference is not a KV-cache implementation.</p><pre tabindex="0" role="region" aria-label="Recirculation fixed mixer reference"><code>def mix_for_recirculation(h_dst, h_src, alpha, beta):
    # Matching [..., d] tensors; norm arithmetic uses float32.
    eps = 1e-6
    dst_norm = h_dst.float().norm(dim=-1, keepdim=True)
    src_norm = h_src.float().norm(dim=-1, keepdim=True)
    scaled_src = (h_src.float() * (dst_norm / src_norm.clamp_min(eps))).to(h_src.dtype)
    return beta * h_dst + alpha * scaled_src
</code></pre><p>Use the model’s actual dtype and test zero/near-zero norms. Clamping prevents division by zero but means tiny nonzero sources need not match the destination norm exactly. Do not detach these states when training the mixer through recurrence.</p></details>`)}
${section('timing','Readout and refinement happen at different times',`<p>Looping processes the current latent state before its selected readout. Feedback carries a completed previous state into the next position. Recirculation uses an ordinary readout and refines history for later positions. A speed comparison is meaningless until these dependencies are specified. Visible reasoning also cycles through vocabulary readout and embeddings; it spends context positions. Residual-space state maintenance and visible reasoning can coexist, rather than replacing one another.</p>${traceLab('recurrence-timing','Three mechanisms, three phases each','Step through looping, feedback and recirculation. Watch which position receives the state.',timingFrames,0,timingBody,'A dependency diagram, not an executable serving scheduler.')}<p>Exact recirculation must make the relevant refined keys and values available before later attention consumes them. The paper discusses overlapping the current ordinary pass with the previous token’s refinement. Such overlap can hide latency only when hardware has capacity; it does not remove arithmetic, energy or memory traffic.</p><p>The studied method uses one extra recirculation, not unlimited repeated refinement. Exact sequential prompt processing is expensive. Proposed blockwise prompt recurrence weakens the dependencies and was not fully evaluated; a whole-prompt block is not equivalent to exact token-by-token refinement. Do not claim a working high-throughput cache engine from a vector-mixing example.</p><p>Capture the residual outputs at s and d. Mix them, rerun blocks after d, then replace affected history entries before later attention reads them. The ordinary first-pass logits remain the readout. Define this order against the model’s cache API; appending another copy of the token changes the sequence instead of refining its state.</p><p>With r extra recirculations, the schedule needs r+1 stack-like executions per input step; only r=1 is evaluated. Extra paths and iterations are proposals. Overlap consumes capacity that could serve another request, so similar single-request latency does not imply equal throughput, energy or memory.</p>`)}
${section('recirc-adapter','Learn how much state to recirculate',`<p>An adaptive mixer reads concatenated source and destination states, then produces feature-wise ${im(String.raw`\boldsymbol\alpha`)} and ${im(String.raw`\boldsymbol\beta`)}. The reported network uses LayerNorm, two hidden-width GELU stages and a final ${im(String.raw`2d`)} sigmoid output, initialized near ${im(String.raw`\alpha=0.1,\quad\beta=0.9`)}.</p><p>The two coefficient vectors are independently bounded in [0,1]; their sum is not constrained to one. This is not necessarily a convex combination. The full-width adapter adds roughly ${im(String.raw`5d^2`)} matrix weights, so it is not free merely because the base model is frozen.</p>${eq(String.raw`\widetilde h_d=\boldsymbol\alpha\odot s'+\boldsymbol\beta\odot h_d`,'Each coefficient vector has hidden width d. ⊙ is feature-wise multiplication; s′ is the norm-matched source.')}<details><summary>Adaptive mixer: build the network, then apply its coefficients</summary><p>The two functions replace the longer class wrapper without changing concatenation order or feature-wise mixing. The explicit final-layer initialization is a teaching implementation of the reported 0.1/0.9 start, not released author code.</p><pre tabindex="0" role="region" aria-label="Recirculation adapter construction reference"><code>import math
import torch

def make_adaptive_mixer(d):
    net = torch.nn.Sequential(
        torch.nn.LayerNorm(2*d), torch.nn.Linear(2*d, d),
        torch.nn.GELU(), torch.nn.Linear(d, d),
        torch.nn.GELU(), torch.nn.Linear(d, 2*d))
    with torch.no_grad():
        net[-1].weight.zero_()
        net[-1].bias[:d].fill_(math.log(0.1/0.9))
        net[-1].bias[d:].fill_(math.log(0.9/0.1))
    return net
</code></pre><p>d is a positive hidden width. Move the network to the input device and dtype before use. Zero output weights make the initial coefficients constant. Earlier layers begin receiving a useful gradient after the final weights update.</p><pre tabindex="0" role="region" aria-label="Recirculation adaptive mixing reference"><code>def adaptive_mix(net, h_dst, h_src):
    logits = net(torch.cat([h_src, h_dst], dim=-1))
    alpha_logits, beta_logits = logits.chunk(2, dim=-1)
    alpha = alpha_logits.sigmoid()
    beta = beta_logits.sigmoid()
    return mix_for_recirculation(h_dst, h_src, alpha, beta)
</code></pre><p>The network has 5d² matrix weights and 8d normalization/bias parameters. Freeze the backbone’s parameters, not the operations carrying gradients to the mixer. A global no-grad context would prevent adapter training. The two coefficient outputs are independent; learned values need not sum to one.</p></details><p>Training uses 250 documents from each of three datasets, 1,024-token windows, 100 steps, batch 32 and AdamW with learning rate 3×10⁻⁴ and weight decay 10⁻⁴. Backpropagation runs through the recurrence to train the mixer. Constant scalar, conditional scalar, constant vector and conditional vector ablations separate adaptability from extra parameters.</p><p>On the reported nine-dataset mean, conditional feature vectors reduce perplexity by about 23%, compared with 8.5% for fixed mixing and 21.6% for full fine-tuning in that comparison. The perplexity adapter experiment uses Gemma3 1B PT. These are not the same aggregation as the ten-dataset fixed-mixing table. Task-specific calibration and downstream adapter training can also change transfer results.</p>`)}
${section('recirc-evidence','Where recirculation helps—and where it does not',`${table('Relative perplexity reduction for fixed mixing; 1,024-token windows',['Dataset','Gemma3 1B','4B','12B'],[['arXiv','14.0%','11.3%','25.2%'],['BookSum','16.0%','16.0%','32.9%'],['PG-19','14.4%','15.7%','35.4%'],['PubMed','11.1%','9.2%','24.5%'],['C4/WebText aggregate','3.9%','4.4%','13.0%'],['LAMBADA','−0.7%','0.5%','−2.8%']])}<p>Negative reductions mean worse perplexity. The authors associate LAMBADA’s mixed result with short sequences and tokenization artifacts. That explanation is a hypothesis, not a correction to the negative results. In one 1B experiment, temperature calibration alone gives 8.48%, recirculation 14.21%, and both 19.55%. This shows the gain is not merely the same temperature adjustment, not that every model gets this gain.</p><p>Effects persist across roughly 20–200 positions in lag analyses, with tested short-context benefits through 256 positions. The first roughly ten tokens can worsen for 1B. Adjectives, adverbs and verbs benefit more than some numerals, determiners and pronouns; plural nouns benefit more than singular nouns. These are observed patterns, not a proved semantic mechanism.</p><p>On Rules, 4B instruction-tuned accuracy moves 82.3→87.3 with fixed settings and 90.8 with task tuning; 12B moves 93.0→98.4→99.4. The task-tuned numbers are not general-purpose held-out settings. Contextual questions improve on two of three tests for 1B/4B, but 12B worsens on two tests and is near ceiling on the third.</p><p>For 4B single-token benchmarks, six of eight improve modestly: MMLU 57.90→58.28, ARC-E 81.78→82.07, ARC-C 54.44→54.86 and PiQA 79.98→80.52. WinoGrande and HellaSwag worsen.</p>${table('GSM8K, Gemma3 4B pretrained, zero-shot CoT',['Method','pass@1','pass@128'],[['Base','29.3','94.9'],['Fixed','30.6','95.4'],['Adaptive','35.5','96.0']])}<p>The adaptive pass@1 gain is about 21% relative accuracy but 8.8% relative error reduction. At pass@128 the error reduction is about 20.9%. Do not interchange those denominators.</p><p>Smaller ARC training can cause regressions; broader MMLU-based adapter training transfers more consistently in reported tests. Limited sweeps on Ministral3, Pythia, Qwen3, Phi2 and other Gemma families do not establish universal compatibility. The cross-family comparison reports less than about 0.5% reduction outside Gemma, versus roughly 5% for Gemma3 1B; normalization and coefficients were not extensively retuned. Gemma’s Peri-LN or data recipe is a possible explanation, not an isolated cause. A training-free layer sweep found robust recirculation regions across Gemma3 sizes, unlike inserting repeated layers into those already-trained models. This does not contradict gains from models trained for looping. The largest tested base is 12B, not a frontier MoE with production long-context serving.</p>`)}
${section('feedback','Carry a wide state into the next token',`<p>Ordinary autoregressive generation exposes a sampled token to the next position. The previous top-layer state remains available indirectly through layer-specific attention history, but is not the next token’s bottom-layer input.</p><p>Full-Bandwidth Transformer adds a direct top-to-next-bottom channel. First compute hₜ₋₁ and sample token xₜ. Its embedding eₜ gates the projected previous state:</p>${eq(String.raw`u_t=(W_uh_{t-1})\odot\sigma(W_ge_t)`,'Two d×d projections; no additive embedding shortcut in this fusion.')}<p>This is asymmetric: the token selects a gate, while the previous state supplies the value. An additive embedding path could let an ordinary pretrained model suppress feedback and preserve its familiar input. The proposed gate removes that direct value shortcut; it does not guarantee useful state learning. Removing that state path removes the value contribution. A sum of state and embedding is a different mechanism.</p><p>The state is already a deterministic function of the prefix: feedback adds computational access, not new external information. It can carry a wide continuous representation without emitting many explanatory tokens. A model can still need visible reasoning tokens or produce an incorrect latent update.</p><p>At ${im(String.raw`d=1536`)}, two matrices add about 4.72M weights. The paper’s under-1% estimated decode-FLOP overhead is not a measured end-to-end latency guarantee. The ordinary KV layout remains, with one additional latest d-vector per request. The projections add ${im(String.raw`2d^2`)} parameters, but the extra buffer and projection traffic are separate serving costs. ${cite('https://arxiv.org/html/2608.08888v1','Full-Bandwidth Transformer')}</p>`)}
${section('feedback-modes','Use feedback at the prompt boundary',`${table('Same checkpoint, distinct execution modes',['Mode','Prompt','Generated tokens'],[['STANDARD','Ordinary embeddings','Ordinary embeddings'],['SOFT','Ordinary prefill','Previous-state fusion'],['FUSED','Ordinary prefill + one feedback prefill pass','Previous-state fusion']])}<p>SOFT puts a boundary between prompt tokens that had no feedback and subsequent tokens that do. FUSED prepares a more compatible feedback prompt history, but roughly doubles forward prefill work. It does not double every generated token’s stack executions.</p><p>The carried state belongs to the request. Reset it for new requests; reorder it with batches and beams; restore it on speculative rollback. A single global buffer shared between requests leaks state. Fixed-address CUDA-graph buffers and EAGLE/MTP integration are implementation proposals in the original, not a verified released serving engine.</p><p>The first position has no previous-token state. It needs an explicit ordinary/start-state convention. Prompt processing must not use the final state of a future position as an earlier token’s input.</p>`)}
${section('feedback-training','Train a sequential channel in parallel passes',`<p>Exact feedback over a whole training sequence would serialize its tokens. The training approximation instead runs several parallel causal passes. Pass one uses embeddings. Later passes read the previous pass’s top state shifted by one position.</p>${eq(String.raw`\begin{aligned}h^{(1)}&=f(e)\\u_t^{(k)}&=\operatorname{fuse}(e_t,h_{t-1}^{(k-1)}),\qquad h^{(k)}=f(u^{(k)})\end{aligned}`,'All states needed by pass k are already available from pass k−1. The causal mask still applies within every pass.')}<p>After K passes, the explicit feedback chain reaches at most K−1 previous positions. That is not the total receptive field: attention can still read the causal prefix. Training keeps gradients through earlier passes; detaching them would change the objective.</p><details><summary>Shift states, preserve the prefix, then run another causal pass</summary><p>e and h have shape [B,T,d]. W_u and W_g use [output,input] matrix order. prefix is an integer tensor [B] giving the number of plain positions in each row. For nonempty sequences, use 1≤prefix≤T so position zero remains plain. Prefix lengths are supplied explicitly; the reference does not invent a sampling distribution.</p><pre tabindex="0" role="region" aria-label="Feedback shifted fusion reference"><code>import torch

def feedback_inputs(e, h, W_u, W_g, prefix):
    previous = torch.cat([torch.zeros_like(h[:, :1]), h[:, :-1]], dim=1)
    values = previous @ W_u.T
    gates = torch.sigmoid(e @ W_g.T)
    fused = values * gates
    positions = torch.arange(e.shape[1], device=e.device)[None, :, None]
    return torch.where(positions &lt; prefix[:, None, None], e, fused)
</code></pre><p>The first placeholder is not a future state. The prefix mask removes it from the model input. Empty sequences produce empty tensors. Padding, loss masks and causal attention remain the caller’s responsibility. This function shows the core gate; apply the model’s RMSNorm and declared jitter policy at the correct integration point.</p><pre tabindex="0" role="region" aria-label="Feedback pass objective reference"><code>def feedback_objective(e, run, loss_fn, fuse, prefixes):
    h = run(e)
    first = loss_fn(h)
    later = []
    for prefix in prefixes:
        h = run(fuse(e, h, prefix))
        later.append(loss_fn(h))
    return first + torch.stack(later).mean() if later else first
</code></pre><p>run returns top states [B,T,d] from a complete causal pass. Each invocation uses that pass’s input history; do not reuse an incompatible prior-pass cache. loss_fn returns one scalar next-token loss using the same output head, shifted targets and valid-token mask. fuse closes over the projection weights. With K passes, supply K−1 prefix tensors. No state is detached, so later losses can train earlier states. These callbacks do not implement a serving engine.</p></details><p>The reported loss averages the feedback-pass losses with λ=1, rather than blindly summing them.</p>${eq(String.raw`\mathcal L_K=\mathcal L_1+\frac1{K-1}\sum_{k=2}^{K}\mathcal L_k\quad(K>1),\qquad\mathcal L_{K=1}=\mathcal L_1`,'Each Lk is a consistently masked next-token loss. The K=1 branch avoids division by zero; later passes retain gradients through the earlier states.')}<p> Random prefix mix-in leaves a plain prefix and applies fusion to the suffix, matching SOFT’s prompt boundary. The averaged term has weight one regardless of how many feedback passes are present. The first-pass loss preserves STANDARD as a fallback and lets the authors check ordinary decoding.</p><p>The schedule starts with ordinary pretraining, then introduces two-pass batches and a small fraction of three-pass batches. Feedback therefore need not be active from initialization. The start point and mixture are heuristic, not a derived optimal schedule.</p><p>A 75%/22%/3% mixture of one/two/three-pass batches averages ${passCompute([.75,.22,.03]).toFixed(2)} forward passes. Thus 200B unique tokens correspond to 256B forward token-pass equivalents; 400B to 512B. These are not full backward FLOPs or measured wall-clock costs. One published 10B/100%-three-pass row lists 40B rather than the arithmetically expected 30B; do not build a general accounting rule from that anomalous row.</p>`)}
${section('feedback-stability','Make repeated feedback survive its own inputs',`<p>A channel trained only once can encounter its own outputs repeatedly at inference. A two-pass 75%/25% mixture becomes unstable at large feedback depth in the reported tests. Replacing three percentage points with three-pass training improves that behavior.</p><p>The report checks 30 feedback prefill iterations and an appendix’s 1,000-iteration stress test. A plateau in those tests is not a global contraction proof or evidence for arbitrarily long agent trajectories.</p><p>Other recipe choices include O(1) depth scaling, RMSNorm around fusion, compatible tied input/output embedding coordinates and uniform jitter with ${im(String.raw`\sigma=0.02`)}. Equation 13 adds jitter to the fused input, before the transformer; adding noise before projection and gating is a different perturbation. These can help the tested system; tying or normalization alone does not prove stability.</p>${eq(String.raw`h_t=f_\theta(u_t+\epsilon;C),\qquad \epsilon\sim\operatorname{Uniform}[-\sigma,\sigma]^d,\quad\sigma=0.02`,'Noise is a training regularizer. State its placement and RMSNorm order when reproducing the recipe; do not add training jitter silently at inference.')}<p>The experimental model is about 1B, with 24 layers, ${im(String.raw`d=1536`)}, gated FFN width 6,656, 16 query heads, eight KV heads, vocabulary 100,352 and context 8,192. Local attention uses a 2,048 window with a global layer every sixth layer. Gated GQA, head gates, Q/K normalization, RoPE and tied embeddings are part of the backbone; they are not all novel consequences of feedback.</p><p>Matrix weights use NorMuon (learning rate 10⁻², decay 0.01); other weights use Adam (5×10⁻⁴, initially zero decay). WSD warms for 200 steps and cools for 25%; z-loss of 10⁻⁵ begins during cooldown. Weight decay follows the learning-rate decay under AdamC. Data uses the Phi-4 mixture. Batch size is roughly 300K tokens versus 1.2M for the 1T baseline—a comparison confound.</p>`)}
${section('feedback-evidence','Separate feedback gains from extra training',`<p>At 200B unique tokens, the original report records base MATH500 pass@1 0.27→SOFT 0.37, HumanEval pass@3 0.31→FUSED 0.34 and MBPP pass@3 0.38→0.40. Code pass@3 is estimated from ten rollouts with separately tuned temperatures from {0.3,0.5,0.7}; it is not greedy accuracy.</p>${table('After context extension and instruction tuning; reported percentages',['Benchmark','200B standard','200B best feedback','400B standard','400B best feedback','1T standard'],[['GSM8K','64.52','67.93','67.90','71.80','70.13'],['MATH500','43.80','45.60','46.00','48.40','47.40'],['HumanEval','42.54','45.92','46.50','47.60','50.01'],['MBPP','38.39','41.22','40.50','41.70','41.93']])}<p>The feedback columns select the best reported feedback mode for each task; they do not describe one fixed mode across all benchmarks. GSM8K and MATH500 use pass@1; HumanEval and MBPP use pass@3.</p><p>Selected runs extend context from 8K to 32K with 12B tokens, then use 6B instruction-tuning tokens; these stages use three passes. At fixed checkpoint, enabling feedback is a cleaner mechanism comparison than contrasting different training-token totals. The latter also changes repeated-pass training, batch size and FUSED prompt work.</p><p>Non-generative evaluations report selected 100B-feedback versus 200B-standard and 200B-feedback versus 400B-standard similarities. Most recurrent-prefill gain occurs on the first added pass, with diminishing returns afterward. This is not a universal 2× reduction in training FLOPs. No end-to-end memory/throughput/latency benchmark is supplied by the original note’s report version.</p><p>Completion tracking tests whether a completed counter equals a required counter. Delayed memory retrieves a bit after irrelevant operations. Latest-write tracking retrieves the most recent value assigned to a queried register. Linear probes at the final position test accessibility at different residual depths. An extra feedback prefill pass makes layer-zero completion 99.6% and delayed-bit retrieval 100% in the cited probes. That does not prove the LM head uses the channel optimally on general language tasks.</p><p>Shorter math completions appear in base-model SOFT tests, but that effect disappears after conventional instruction tuning. Off-policy reasoning traces are the authors’ explanation, not a demonstrated causal result. On-policy RL and feedback-specific data are proposals. <a href="https://arxiv.org/abs/2607.15178">T²MLR</a> carries a previous middle-layer state to an earlier middle layer. <a href="https://arxiv.org/abs/2605.26797">Latent Recurrent Transformer</a> explores cross-position injection through attention/residual paths. These are different placements, not evidence that top-to-input is globally optimal.</p><p>Version 1 studies approximately 1B models, with main recurrent runs up to 400B tokens. It supplies neither released weights nor an official end-to-end implementation. Free-form tests cover four tasks. Fusion form, connection placement, loss weights and stabilizers are not exhaustively isolated. Peak training memory, wall time and distributed serving costs remain unmeasured.</p>`)}
${section('nanbeige','A fixed-loop model recipe',`<p>Nanbeige4.2 combines two loop passes with a compact parameter budget, rather than Ouro’s adaptive halting. The original configuration records 22 physical layers, effective depth 44, hidden width 3,072, FFN width 10,752, 48 query heads, eight KV heads, head width 128 and vocabulary 166,144.</p><p>The released implementation resolves the apparent width mismatch. Query heads occupy ${im(String.raw`48\times128=6144`)} coordinates, while the residual stream stays 3,072 wide. Its explicit head-width field overrides the usual hidden-width/head-count fallback. The output projection maps the concatenated head results back to the residual width; ${im(String.raw`d=h\,d_{\mathrm{head}}`)} is not a required identity.</p>
${table('Nanbeige 4.2 attention projection widths; one token, biases disabled',['Projection','Input → output width','Head view'],[['Query',im(String.raw`3072\longrightarrow6144`),'48 query heads × 128'],['Key',im(String.raw`3072\longrightarrow1024`),'8 KV heads × 128'],['Value',im(String.raw`3072\longrightarrow1024`),'8 KV heads × 128'],['Output',im(String.raw`6144\longrightarrow3072`),'Concatenated query-head results → residual stream']]).replace('<table>','<table style="min-width:640px">')}
<p>Each KV group serves ${im(String.raw`\frac{48}{8}=6`)} query heads. Wider queries do not change the number of stored KV heads. This shape check explains the architecture, not its quality or measured throughput. ${cite('https://huggingface.co/Nanbeige/Nanbeige4.2-3B/resolve/b82e54bd609793562a75cbf9337970a93369eab5/config.json','Pinned checkpoint configuration')} · ${cite('https://huggingface.co/Nanbeige/Nanbeige4.2-3B/resolve/b82e54bd609793562a75cbf9337970a93369eab5/modeling_nanbeige.py','Pinned attention implementation')}.</p><p>The report lists about 3B non-embedding and 4B total parameters, 28T pretraining tokens and 256K context, with thinking and non-thinking modes. Reused layers do not turn 28T unique tokens into 56T independent data.</p><p>Two loops are reported as the chosen quality/efficiency tradeoff; additional loops bring marginal gains and instability. The quoted roughly 75% token-processing efficiency lacks the fully controlled serving setup needed for a universal speed claim. Shared loop KV saves about half the loop cache but weakens gains; the released recipe retains separate loop caches according to the original note.</p><p>From-scratch training outperforms the reported upcycling trial, but architecture, data and recipe details are not isolated. Math/code/STEM, synthetic QA and agent data change alongside the model. Its environment construction, SFT/RL stages and full benchmark comparisons are in <a href="${link('models/compact-recipes#nan42')}">the Nanbeige4.2 recipe →</a>. Looping alone does not explain those training choices.</p>`)}
${section('implementation','Checks before claiming a saving',`<p>First identify the state and dependency: current token across depth, previous token across time or refined history for later attention. Test a future-token perturbation: earlier predictions must not change. Test start-state initialization and request reset separately.</p><p>For tied layers, verify parameter identity and optimizer deduplication. Log per-round state RMS, branch RMS, gradient RMS and update/state ratios. Count every active matrix visit. In truncated training, record exactly which cycles receive gradients.</p><p>For halting, conserve exit mass and force the budget’s last exit. Validate thresholds against cumulative mass. Compare full and reused caches independently for prompt and decode. For recirculation, test layer indexing, norm clamps, cache invalidation and the readout/refinement boundary.</p><p>For feedback, shift previous states, preserve plain-prefix boundaries and compare one-, two- and three-pass losses. Verify carried states under batching, beam reordering and speculative rollback. A correct vector formula is not a correct distributed scheduler.</p><p>Finally measure unique tokens, token-passes, actual training FLOPs, peak memory, prefill/decode latency and throughput at matched quality. Parameter memory, KV storage and serial depth are different budgets. Link architecture to <a href="${link('training/parallelism')}">Parallelism →</a> rather than interpreting every theoretical FLOP reduction as a deployment win.</p>`)}
${section('sources','Sources and connected topics',`<p>${cite('https://arxiv.org/abs/2510.25741','Ouro (2025)')} · ${cite('https://arxiv.org/abs/2605.09165','Sparse Layers (2026)')} · ${cite('https://arxiv.org/abs/2607.13491','DeepLoop')} · ${cite('https://arxiv.org/abs/2608.17981','Recirculation')} · ${cite('https://arxiv.org/abs/2608.08888','Full-Bandwidth Transformer')} · ${cite('https://www.microsoft.com/en-us/research/publication/full-bandwidth-transformer/','Microsoft Research publication')}</p><p>${cite('https://arxiv.org/abs/1807.03819','Universal Transformers')} · ${cite('https://arxiv.org/abs/2107.05407','PonderNet')} · ${cite('https://arxiv.org/abs/2203.00555','DeepNet / DeepNorm')} · ${cite('https://huggingface.co/Nanbeige/Nanbeige4.2-3B','Nanbeige4.2 model')}</p><p>For the broader compute budget, connect <a href="${link('training/scaling')}">Scaling Laws</a> to <a href="${link('post-training/reasoning#compute-allocation')}">reasoning compute allocation</a> and <a href="${link('execution/serving#economics')}">serving economics</a>. <a href="${link('models/compact-recipes')}">Compact model recipes</a> preserve data and post-training choices that looping alone cannot explain. <a href="${link('models/tokenization#concepts')}">Concept-space models</a> change the representation unit instead of adding recurrent depth.</p><p>Recirculation’s direct mixing differs from <a href="${link('models/transformers#depth')}">Attention Residuals</a>, which retrieves earlier depth states. Connect its coordinate assumptions to <a href="${link('models/transformers#normalization')}">normalization</a> and its retained path to <a href="${link('models/transformers#residual')}">residual connections</a>.</p><p>Connect gates to <a href="${link('models/transformers#activations')}">activation functions</a>, output probabilities to <a href="${link('training/objectives#binary')}">binary cross-entropy</a>, and update monitoring to <a href="${link('training/optimization#gradient-diagnostics')}">gradient diagnostics</a>. These are different roles: an LSTM gate is not a supervised binary target.</p><p>The bounded demonstrations illustrate mechanisms. Benchmark tables contain reported results under their stated conditions, not outputs of the animations.</p>`)}
`);}
export function mountRecurrence(scope=document){mountTopic(scope,recurrenceMeta.slug,article=>{const bind=(selector,draw)=>{const lab=article.querySelector(selector),controls=[...lab.querySelectorAll('input,select')],update=()=>lab.querySelector('[data-body]').innerHTML=draw(...controls.map(c=>c.value));for(const control of controls)control.addEventListener(control.tagName==='SELECT'?'change':'input',update);};bind('[data-cell-lab]',f=>cellBody(Number(f)));bind('[data-exit-lab]',(profile,q)=>exitBody(profile,Number(q)));bind('[data-scaling-lab]',(r,p,a)=>scaleBody(Number(r),Number(p),a==='aligned'));bind('[data-mix-lab]',(a,rule)=>mixBody(Number(a),rule==='addition'));mountTrace(article,'loop-unroll',loops,loopBody);mountTrace(article,'recurrence-timing',timingFrames,timingBody);});}
recurrenceMeta.searchText=recurrenceReader(()=> '').replace(/<[^>]*>/g,' ');
